// Google retires models too: list them with GET /v1beta/models and change this line if calls fail
const TRANSCRIBE_MODEL = 'gemini-3.5-transcribe';

// Transcription prompt V2: domain + language context (V1 was Whisper's one-line hint)
const TRANSCRIBE_PROMPT = 'Emergency voice note sent to Tunisian Civil Protection during a flood. The speaker may use Tunisian Derja (Tunisian Arabic), French, English or a mix, often with rain, wind or panic in the background. Transcribe verbatim: keep Derja in Arabic script and French/English words in Latin script. Do not translate, summarise or correct grammar. Keep numbers, street names and landmarks exactly as spoken.';

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) throw new Error('No audio binary found in field "data"');
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const mime = (bin.mimeType || '').startsWith('audio/') ? bin.mimeType : 'audio/ogg'; // Telegram voice notes are Ogg/Opus
  results.push({
    json: {
      model: TRANSCRIBE_MODEL,
      request_body: {
        contents: [{ parts: [{ text: TRANSCRIBE_PROMPT }, { inline_data: { mime_type: mime, data: buffer.toString('base64') } }] }],
      },
    },
    pairedItem: { item: i },
  });
}
return results;

// gemini-3.5-transcribe returns the text in parts[].audioTranscription.text (not parts[].text)
const parts = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts) || [];
const text = parts
  .map((p) => (p.audioTranscription && p.audioTranscription.text) || p.text || '')
  .join(' ')
  .trim();
if (!text) throw new Error('Gemini returned an empty transcript: call transcribe_voice_backup');
return { json: { text, asr_engine: 'gemini-3.5-transcribe' } };
